/** The findings still standing (not waived), counted under each severity; every severity is present. */
export function openBySeverity(findings: Finding[]): Record<Severity, number> {
    const counts: Record<Severity, number> = { advisory: 0, minor: 0, major: 0, critical: 0 };
    for (const finding of findings) {
        if (!finding.waived) {
            counts[finding.severity] += 1;
        }
    }
    return counts;
}

